'use strict';
let sampleSession=null;
function samplingSettings(){return {channel:$('#sampleChannel').value,length:$('#sampleLength').value,monitor:$('#sampleMonitor').value,thresholdOn:$('#sampleThresholdOn').checked,threshold:Math.max(-96,Math.min(0,Number.isFinite(+$('#sampleThreshold').value)?+$('#sampleThreshold').value:-30)),inputFx:$('#sampleInputFx').checked,chopLive:$('#sampleChopLive').checked}}
