function cleanupSample(session){const owned=sampleSession===session;clearInterval(session.timer);clearTimeout(session.limit);clearTimeout(session.begin);session.stream?.getTracks().forEach(t=>t.stop());session.fx?.dispose();if(session.native){try{session.input?.disconnect(session.native);session.native.disconnect();session.native.port.close()}catch{}}for(const node of session.nodes||[])try{node.disconnect()}catch{}if(owned){sampleSession=null;$('#mic').textContent='● MICRO';$('#mic').classList.remove('red');$('#sampleInputState').textContent='Entrée fermée.';for(const id of ['sampleDevice','sampleChannel','sampleLength','sampleInputFx','sampleChopLive'])$('#'+id).disabled=false}}
function stopSampling(discard=false){const session=sampleSession;if(!session)return;session.discard=discard;if(session.rec?.state==='recording')session.rec.stop();else cleanupSample(session)}
function beginSampling(session){if(sampleSession!==session||session.phase==='recording')return;session.phase='recording';session.started=ctx.currentTime;session.rec.start();const seconds=session.options.length==='sequence'?Math.min(59,sequenceLength()*60/tempo()/4):59;session.duration=session.options.length==='sequence'?seconds:null;session.limit=setTimeout(()=>stopSampling(),seconds*1000);$('#mic').textContent='■ TERMINER';$('#sampleInputState').textContent='Enregistrement sur '+padName(session.target)+' · '+(session.duration?seconds.toFixed(2)+' s':'libre')}
function samplingBoundary(time){const session=sampleSession;if(session?.phase==='boundary'){if(session.options.thresholdOn&&session.analyser){const data=new Float32Array(1024);session.analyser.getFloatTimeDomainData(data);if(Math.sqrt(data.reduce((n,v)=>n+v*v,0)/data.length)<10**(session.options.threshold/20)){status('Armé : seuil non atteint, attente du prochain tour.');return}}session.phase='scheduled';session.begin=setTimeout(()=>beginSampling(session),Math.max(0,(time-ctx.currentTime)*1000))}}
function captureLiveSlice(){const s=sampleSession;if(s?.phase!=='recording'||!s.options.chopLive)return false;const time=ctx.currentTime-s.started;if(s.markers.length<16&&time-s.markers.at(-1)>.03)s.markers.push(time);status('Marqueur de tranche '+s.markers.length+' posé.');return true}
$('#mic').onclick=async()=>{if(sampleSession){stopSampling();return}if(micPending)return;micPending=true;const options=samplingSettings();if(options.length==='sequence'&&sequenceLength()*60/tempo()/4>59){status('La séquence dépasse 59 secondes : réduisez sa longueur ou utilisez une prise libre.');micPending=false;return}const target=selected,pad=pads[target],owner=pads;let session;try{await audio();if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Enregistrement indisponible.');const device=$('#sampleDevice').value;session={target,pad,initialData:pad.data,owner,options,phase:'opening',nodes:[],markers:[0],chunks:[]};sampleSession=session;for(const id of ['sampleDevice','sampleChannel','sampleLength','sampleInputFx','sampleChopLive'])$('#'+id).disabled=true;session.stream=await navigator.mediaDevices.getUserMedia({audio:{...(device?{deviceId:{exact:device}}:{}),channelCount:2,echoCancellation:false,noiseSuppression:false,autoGainControl:false}});if(sampleSession!==session){cleanupSample(session);return}const source=ctx.createMediaStreamSource(session.stream),split=ctx.createChannelSplitter(2),merge=ctx.createChannelMerger(2),input=ctx.createGain(),processed=ctx.createGain(),destination=ctx.createMediaStreamDestination(),monitor=ctx.createGain(),analyser=ctx.createAnalyser();session.nodes.push(source,split,merge,input,processed,destination,monitor,analyser);source.connect(split);const mono=options.channel!=='stereo',channels=session.stream.getAudioTracks()[0]?.getSettings?.().channelCount||2,right=options.channel==='right'&&channels>1?1:0;split.connect(merge,mono?right:0,0);split.connect(merge,mono?right:channels>1?1:0,1);merge.connect(input);session.input=input;let effectsInput=input;if(options.inputFx){const settings=effectSettings();if(settings.enabled||settings.delayEnabled){const intermediate=ctx.createGain();session.nodes.push(intermediate);session.native=await PocketDSP.connect(ctx,input,settings,intermediate);effectsInput=intermediate}session.fx=PocketFX.create(ctx,effectsInput,processed,classicSettings(true))}else input.connect(processed);processed.connect(destination);processed.connect(monitor).connect(masterBus);input.connect(analyser);analyser.fftSize=1024;session.analyser=analyser;const levels=new Float32Array(1024),mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));session.rec=new MediaRecorder(destination.stream,mime?{mimeType:mime}:{});recorder=session.rec;stream=session.stream;session.rec.ondataavailable=e=>{if(e.data.size)session.chunks.push(e.data)};session.rec.onstop=async()=>{cleanupSample(session);if(session.discard||!session.chunks.length)return;micPending=true;$('#mic').textContent='DÉCODAGE…';try{const decoded=await ctx.decodeAudioData(await new Blob(session.chunks,{type:session.rec.mimeType}).arrayBuffer()),length=Math.max(1,Math.round((session.duration??Math.min(59,decoded.duration))*sr)),off=new OfflineAudioContext(mono?1:2,length,sr),node=off.createBufferSource();node.buffer=decoded;node.connect(off.destination);node.start();const b=await off.startRendering();if(pads!==owner||pads[target]!==pad||pad.data!==session.initialData)throw Error('Le projet ou le pad cible a changé : prise ignorée.');if(pads.reduce((n,p,i)=>n+(i===target?0:p.data.length*(p.right?2:1)),0)+b.length*b.numberOfChannels>sr*240)throw Error('Mémoire audio pleine.');remember();Object.assign(pad,{data:b.getChannelData(0).slice(),right:mono?null:b.getChannelData(1).slice(),start:0,end:1,loopStart:0,name:'PRISE '+padName(target),slices:[...session.markers.filter(t=>t<b.duration-.01),b.duration]});updateSelected(target);changed();status('Prise enregistrée sur '+padName(target)+'.')}catch(e){status('Prise non conservée : '+e.message)}finally{micPending=false;$('#mic').textContent='● MICRO'}};session.phase=options.length==='sequence'&&playing?'boundary':options.thresholdOn?'threshold':'ready';session.timer=setInterval(()=>{if(sampleSession!==session)return;const monitorMode=$('#sampleMonitor').value,auto=monitorMode==='auto'&&$('.machine').classList.contains('editor-mode');monitor.gain.setTargetAtTime(monitorMode==='on'||auto?1:0,ctx.currentTime,.01);if(session.phase==='threshold'){if(!$('#sampleThresholdOn').checked){beginSampling(session);return}analyser.getFloatTimeDomainData(levels);const rms=Math.sqrt(levels.reduce((n,v)=>n+v*v,0)/levels.length);$('#sampleInputState').textContent='Armé · entrée '+(20*Math.log10(Math.max(1e-6,rms))).toFixed(1)+' dBFS';if(rms>=10**(Math.max(-96,Math.min(0,+$('#sampleThreshold').value))/20))beginSampling(session)}},25);monitor.gain.value=options.monitor==='on'?1:0;if(session.phase==='ready')beginSampling(session);else{$('#mic').textContent='■ ANNULER ARMEMENT';$('#sampleInputState').textContent=session.phase==='boundary'?'Armé · prochain début de séquence.':'Armé · attente du seuil.'}$('#mic').classList.add('red');const devices=await navigator.mediaDevices.enumerateDevices();$('#sampleDevice').replaceChildren();const def=document.createElement('option');def.value='';def.textContent='Entrée par défaut';$('#sampleDevice').append(def);for(const d of devices.filter(d=>d.kind==='audioinput')){const option=document.createElement('option');option.value=d.deviceId;option.textContent=d.label||'Entrée audio';$('#sampleDevice').append(option)}$('#sampleDevice').value=device}catch(e){if(session)cleanupSample(session);status('Entrée indisponible : '+e.message)}finally{micPending=false}};
for(const id of ['sampleChannel','sampleLength','sampleMonitor','sampleThresholdOn','sampleThreshold','sampleInputFx','sampleChopLive'])$('#'+id).onchange=changed;
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSampling()});window.addEventListener('pagehide',()=>stopSampling());restoreSampling(restoredExtra?.sampling);
